/* ============================================================
   PDF · la letra de la app (Archivo) dentro de los documentos
   Archivo (SIL Open Font License 1.1), en cuatro estilos fijos sacados de la fuente variable que usa la
   interfaz, solo con los caracteres latinos que dejan pasar los PDF (pdfSafe). Cada PDF la incrusta
   (unos 110 kB). Más abajo, la de los títulos y la del guion.
   ============================================================ */
const PDF_FONT_B64 = {
  normal: '',
  bold: '',
  italic: '',
  bolditalic: '',
};
/* los títulos en Familjen Grotesk (como en la app) y lo que viene del guion en Courier Prime, la Courier de los
   guionistas que usa la app (mismo ancho de letra que la Courier: el formato no cambia). SIL Open Font License 1.1;
   solo los caracteres latinos que dejan pasar los PDF (pdfSafe), sin «hinting» (unos 130 kB en total) */
const PDF_TITLE_B64 = {
  bold: '',
  normal: '',
};
const PDF_MONO_B64 = {
  normal: '',
  italic: '',
  bold: '',
  bolditalic: '',
};
const PDF_UI = 'archivo', PDF_TITLE = 'familjen', PDF_MONO = 'courierprime';
function pdfFonts(doc) {
  try {
    for (const [st, b] of Object.entries(PDF_FONT_B64)) { doc.addFileToVFS(`Archivo-${st}.ttf`, b); doc.addFont(`Archivo-${st}.ttf`, PDF_UI, st); }
    return true;
  } catch (e) { console.warn('PDF: no se pudo incrustar la letra', e); return false; }
}
/* la de los títulos y la del guion se incrustan solo si el documento las usa (cada una pesa lo suyo) */
function pdfFontOn(doc, name) {
  doc._fx = doc._fx || {};
  if (doc._fx[name] != null) return doc._fx[name];
  try {
    const [B, file] = name === PDF_TITLE ? [PDF_TITLE_B64, 'Familjen'] : [PDF_MONO_B64, 'CourierPrime'];
    for (const [st, b] of Object.entries(B)) { doc.addFileToVFS(`${file}-${st}.ttf`, b); doc.addFont(`${file}-${st}.ttf`, name, st); }
    return (doc._fx[name] = true);
  } catch (e) { console.warn('PDF: no se pudo incrustar la letra', name, e); return (doc._fx[name] = false); }
}
